// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: only the current owner may call setOwner.
        address current = c.owner();
        vm.prank(current);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        // General rule: when the current owner calls setOwner, the call succeeds
        // and returns exactly true, regardless of the proposed owner address.
        // The mutant returns (owner != _owner), which is false when the proposed
        // owner equals the current owner (or any address it fails to change to).
        assertTrue(ok, "owner-initiated setOwner must return true");
    }
}

